window.BANQUE_INFINI = {"module":"annee-1/pratique/semestre-1/positionnements-transferts","titre":"Positionnements, mobilité et transferts","sources":[{"t":"Cahier — positions, mobilité et transferts","q":"cahier-positions/quiz.html","f":"cahier-positions/fiche.html"},{"t":"Marche et aides à la marche","q":"marche/quiz.html","f":"marche/fiche.html"},{"t":"Décubitus ventral, Fowler et mobilité précoce","q":"mobilite-precoce/quiz.html","f":"mobilite-precoce/fiche.html"},{"t":"Positionnements et escarres","q":"positionnements/quiz.html","f":"positionnements/fiche.html"},{"t":"Transferts","q":"transferts/quiz.html","f":"transferts/fiche.html"}],"questions":[{"q":"Quels sont les points d'appui en position assise ?","o":["Omoplates, ischions, sacrum, creux poplités et métatarses","Occiput, épineuses, sacrum, coudes et calcanéums","Oreille, épaule, côtes, trochanter et malléole externe","Visage, épaules, épines iliaques, rotules et orteils"],"r":0,"e":"La position assise a ses propres zones à risque, souvent oubliées. À l'omoplate, c'est l'épine qui appuie ; les ischions sont les tubérosités ischiatiques.","s":0},{"q":"Quels points d'appui concernent le décubitus ventral ?","o":["Visage ou front, épaule, épine iliaque, rotule","Occiput, sacrum, coudes et calcanéums","Ischions, sacrum, creux poplité et talons","Oreille, épaule, trochanter, condyle et malléole externe"],"r":0,"e":"Ce sont les reliefs antérieurs du corps. Le visage appuie par l'oreille, ou par le front.","s":0},{"q":"Quelles sont les indications du décubitus ventral ?","o":["Escarres postérieures, insuffisance respiratoire grave","Toute immobilisation prolongée, quelle qu'en soit la cause","Troubles digestifs, reflux et nausées post-opératoires","Agitation, confusion et patients non coopérants"],"r":0,"e":"Quatre indications, mais la position est généralement mal tolérée. S'y ajoutent les suites post-opératoires et le raccourcissement des fléchisseurs de hanche.","s":0},{"q":"Le décubitus ventral est-il bien toléré ?","o":["Non, il est généralement mal toléré","Oui, c'est la position préférée","Il est neutre","Il n'est jamais utilisé"],"r":0,"e":"Le cahier le signale explicitement.","s":0},{"q":"Combien de stratégies de prévention des escarres le cahier liste-t-il ?","o":["Neuf","Cinq","Sept","Douze"],"r":0,"e":"Du miroir aux soins des vêtements, en passant par les changements toutes les 2 heures.","s":0},{"q":"Quelle organisation la prise en charge des escarres suppose-t-elle ?","o":["Une équipe multidisciplinaire aux objectifs communs","Le kinésithérapeute seul, qui coordonne tous les soins","L'infirmier seul, chargé des retournements","La famille seule, formée aux gestes de prévention"],"r":0,"e":"L'intégration de l'équipe est explicitement mentionnée.","s":0},{"q":"Où placer le coussin en décubitus dorsal, en plus des membres ?","o":["Sous la tête et les épaules","Sous le bassin","Sous les lombes uniquement","Sous les talons uniquement"],"r":0,"e":"Un coussin sous la tête et les épaules, puis sous les MS et les MI.","s":0},{"q":"Que faut-il éviter au niveau de la tibio-tarsienne en décubitus dorsal ?","o":["Le poids des vêtements et l'appui des talons","La position neutre de la cheville","L'abduction des orteils et du pied","La rotation externe de toute la jambe et du pied"],"r":0,"e":"Les talons ne doivent pas être appuyés.","s":0},{"q":"Quelle est la différence de l'option 1 pour le DL sur le côté atteint ?","o":["Coude fléchi","Coude en extension","Membres supérieurs libres","Bras au-dessus de la tête"],"r":0,"e":"Option 1 : coude fléchi ; option 2 : coude en extension ; option 3 : MS libres.","s":0},{"q":"Quelle est la différence de l'option 2 pour le DL sur le côté atteint ?","o":["Coude en extension","Coude fléchi","MS libres","Coude en rotation interne"],"r":0,"e":"Seule la position du coude change entre les options 1 et 2.","s":0},{"q":"Quelle est la particularité de l'option 3 pour le DL sur le côté atteint ?","o":["Les membres supérieurs sont libres","Le coude supra-latéral est fléchi à 90°","Le coude supra-latéral est tendu","Les membres inférieurs sont tendus"],"r":0,"e":"Dans les trois options, les MI restent en flexion avec des coussins.","s":0},{"q":"Comment ajuster un patient dans le lit à deux personnes selon le cahier ?","o":["Lit à hauteur des trochanters, déplacement avec le drap","En tirant le patient par les épaules, lit au plus bas","En soulevant le patient par les aisselles, à deux","En inclinant le lit tête en bas, puis en le tirant"],"r":0,"e":"Il ne faut ni tirer par la ceinture scapulaire, ni traîner le drap. Les segments du lit sont au même niveau ; la hauteur est celle du grand trochanter des intervenants.","s":0},{"q":"À quelle hauteur régler le lit avant un ajustement à deux personnes ?","o":["À hauteur du grand trochanter des intervenants","Au plus bas, pour limiter le risque de chute","Au plus haut, pour éviter de se pencher","À hauteur de la taille du patient allongé"],"r":0,"e":"C'est le réglage qui protège le rachis des soignants.","s":0},{"q":"Comment ajuster un patient dans le lit à une seule personne ?","o":["Le patient fait le pont, le kiné appuie vers les pieds","Le kiné tire seul le drap vers la tête du lit","Le kiné soulève le bassin à deux mains","Le kiné roule le patient sur le côté, puis le fait remonter"],"r":0,"e":"Le pont pelvien permet au patient de participer activement. Le patient a les genoux fléchis et les pieds appuyés.","s":0},{"q":"Où placent-on les mains du kiné pour rouler un patient avec assistance ?","o":["Une sur la ceinture scapulaire, l'autre sur la pelvienne","Les deux sur le bassin, de chaque côté","Les deux sur les épaules, pour tirer le haut du tronc vers soi","Une sur la tête, l'autre sous les genoux"],"r":0,"e":"Le roulement doit être effectué en bloc.","s":0},{"q":"Comment un patient roule-t-il sans assistance ?","o":["Bras écartés, jambes fléchies, puis il roule paumes jointes","Bras le long du corps, il tire sur la barrière du lit","Jambes tendues, il pousse fort sur les deux talons","Genoux contre le torse, il pivote sur les épaules"],"r":0,"e":"Le geste des paumes jointes lance la rotation du tronc.","s":0},{"q":"Que fait le MS distal du kiné lors du passage assis avec assistance ?","o":["Il sort les jambes de la table, créant un pendule","Il pousse les épaules du patient vers l'avant","Il soutient la tête, contrôlant la ceinture scapulaire","Il stabilise le bassin contre la table"],"r":0,"e":"Le MS proximal soutient la tête et contrôle la ceinture scapulaire. Ce mouvement pendulaire aide à redresser le tronc.","s":0},{"q":"Comment un patient passe-t-il en position assise sans assistance ?","o":["Un bras sous la poitrine, l'autre sur la table pour pousser","Il tire sur un cadre de lit, les jambes tendues","Il s'appuie sur les deux coudes, puis se redresse seul","Il roule sur le ventre, puis se redresse sur les genoux"],"r":0,"e":"Le push-up du MS supra-latéral remplace l'aide extérieure. Le membre supérieur infra-latéral est sous la poitrine, le supra-latéral fait un push-up sur la table.","s":0},{"q":"Où le kiné soutient-il les genoux lors du passage debout avec assistance ?","o":["Sur la face latérale externe","Sur la face antérieure","Sur la face postérieure","Sous la rotule"],"r":0,"e":"L'appui dépend de la dysfonction présentée par le patient.","s":0},{"q":"Quelle consigne donner au patient pour se lever sans assistance ?","o":["Nez vers les pieds, puis tendre colonne et genoux","Pousser sur les talons en gardant le dos bien droit","Tirer sur la barrière du lit, bras tendus","Se propulser d'un coup, sans s'aider des mains"],"r":0,"e":"Les deux mains au bord du lit, puis le mouvement nez-vers-pieds. On se penche d'abord en avant, les deux mains au bord du lit.","s":0},{"q":"Combien de causes d'un mauvais transfert le cahier liste-t-il ?","o":["Dix","Six","Huit","Douze"],"r":0,"e":"De la mauvaise évaluation du poids aux vêtements inadaptés.","s":0},{"q":"Quelle cause d'échec concerne la morphologie des soignants ?","o":["Des transporteurs de tailles différentes","Des transporteurs trop jeunes et peu expérimentés","Des transporteurs du même sexe","Un nombre pair de transporteurs"],"r":0,"e":"La différence de taille déséquilibre la charge.","s":0},{"q":"Quelle cause d'échec concerne la biomécanique ?","o":["Des leviers trop grands","Des leviers trop courts","Une base d'appui trop large","Une flexion des genoux excessive"],"r":0,"e":"Le levier doit être le plus court possible.","s":0},{"q":"Combien de questions faut-il se poser pour choisir un transfert ?","o":["Dix","Cinq","Sept","Douze"],"r":0,"e":"De la capacité d'aide du patient au matériel sensible à transporter.","s":0},{"q":"Quelle question concerne la peau du patient ?","o":["La peau est-elle intacte ?","La peau est-elle sèche ?","Le patient transpire-t-il ?","La peau est-elle pigmentée ?"],"r":0,"e":"L'intégrité cutanée conditionne les prises possibles.","s":0},{"q":"Quelle question concerne la communication ?","o":["A-t-il des troubles du langage, de l'ouïe ou de la vue ?","Parle-t-il couramment la langue du soignant ?","Est-il coopératif et motivé pour faire le transfert ?","Est-il anxieux, voire agité, à l'idée d'être déplacé ?"],"r":0,"e":"Ces troubles modifient les commandes verbales.","s":0},{"q":"Quel élément matériel faut-il vérifier sur le fauteuil roulant ?","o":["Les freins, les pieds et l'orientation des roues","Les freins seuls, bloqués des deux côtés du fauteuil","Les accoudoirs seuls, retirés du côté du transfert","La pression des pneus avant chaque usage"],"r":0,"e":"C'est le point 4 de la minimisation des risques. Les roues doivent être tournées vers l'avant.","s":0},{"q":"Combien de types de transferts le cahier distingue-t-il ?","o":["Cinq","Trois","Quatre","Six"],"r":0,"e":"3/4 transporteurs, australienne, siège, 2 transporteurs, 1 transporteur.","s":0},{"q":"Quelle commande verbale le cahier recommande-t-il ?","o":["Une commande unique, par exemple « 1, 2, 3 »","Plusieurs commandes, une par intervenant","Un signal silencieux, fait de la main","Un compte à rebours, à partir de 10"],"r":0,"e":"Une commande unique évite toute désynchronisation.","s":0},{"q":"Quel appui le cahier recommande-t-il aux transporteurs pendant les contacts manuels ?","o":["S'appuyer contre le matelas","S'appuyer sur le patient","S'appuyer sur la barrière","Ne prendre aucun appui"],"r":0,"e":"L'appui contre le matelas stabilise et décharge le rachis.","s":0},{"q":"En décubitus dorsal, les points d'appui comprennent :","o":["Nuque, épineuses, olécranes, sacrum et calcanéums","Oreille, épaule, côtes, trochanter et malléole externe","Visage, épaule, épine iliaque, rotule et orteils","Omoplates, ischions, sacrum, creux poplités et métatarses"],"r":0,"e":"Chaque position a ses zones de pression propres, à connaître pour la prévention des escarres. S'y ajoutent l'épine de l'omoplate et la zone fessière.","s":0},{"q":"En décubitus latéral, les points d'appui sont :","o":["Oreille, épaule, côtes, trochanter et malléole externe","Nuque, épineuses, olécranes, sacrum, fesses et calcanéums","Visage, épaule, épine iliaque, rotule et orteils","Omoplates, ischions, sacrum, creux poplités"],"r":0,"e":"Le décubitus ventral appuie, lui, sur le visage ou le front, l'épaule, l'épine iliaque et la rotule. Le condyle externe du genou est aussi un point d'appui.","s":0},{"q":"Les changements de position doivent avoir lieu :","o":["Toutes les 2 heures","Toutes les 4 heures","Toutes les 8 heures","Une fois par jour"],"r":0,"e":"C'est l'une des neuf stratégies de prévention des escarres.","s":0},{"q":"Parmi les neuf stratégies de prévention des escarres figurent :","o":["L'autocontrôle au miroir, les lits articulés et l'hygiène","Le seul changement de position, toutes les deux heures","La seule alimentation, enrichie en protéines et en vitamines","Le seul matériel anti-escarres, sans autre mesure"],"r":0,"e":"La prise en charge repose sur une équipe multidisciplinaire aux objectifs communs. S'y ajoutent le matériel anti-escarres, l'alimentation adéquate et les soins des vêtements.","s":0},{"q":"En décubitus dorsal, les membres supérieurs se placent :","o":["Sur coussin, légèrement abduits et en rotation externe","Sans coussin, en adduction stricte contre le tronc","Sur coussin, en rotation interne et coudes fléchis à 90°","Le long du corps, sans coussin ni abduction"],"r":0,"e":"Les membres inférieurs sont également légèrement abduits sur coussin, et la tibio-tarsienne en position neutre, talons non appuyés.","s":0},{"q":"En décubitus latéral, l'épaule infra-latérale doit être :","o":["Légèrement avancée, la main posée sur l'oreiller","Placée sous le tronc, le bras tendu en arrière du dos","En rotation interne, la main sous la hanche","Comprimée par le thorax, le coude fléchi"],"r":0,"e":"Le membre supérieur supra-latéral repose sur un coussin à l'horizontale, main en position fonctionnelle.","s":0},{"q":"Dans les trois options de décubitus latéral du côté atteint, le point commun est :","o":["Les membres inférieurs fléchis, calés par des coussins","Un coude supra-latéral toujours fléchi sur coussin","Des membres supérieurs toujours libres et sans appui","Des membres inférieurs en extension, sans coussin entre eux"],"r":0,"e":"Les options se distinguent par la position du membre supérieur : coude fléchi, coude en extension, ou membres libres.","s":0},{"q":"Le décubitus ventral est indiqué notamment en cas :","o":["D'escarres postérieures ou d'insuffisance respiratoire","D'escarres antérieures, sur les rotules","De troubles de déglutition, avec risque de fausse route","D'instabilité cervicale après un traumatisme"],"r":0,"e":"Il est généralement mal toléré par le patient. S'y ajoutent les suites post-opératoires et le raccourcissement des fléchisseurs de hanche.","s":0},{"q":"Pour ajuster un patient dans le lit à deux personnes, le lit doit être réglé :","o":["À hauteur du grand trochanter des intervenants","À hauteur des genoux des intervenants","Le plus bas possible, pour la sécurité","Le plus haut possible, au niveau de la poitrine"],"r":0,"e":"Il faut déplacer avec le drap, sans tirer par la ceinture scapulaire ni traîner le drap, segments du lit au même niveau.","s":0},{"q":"Pour ajuster un patient seul, le kiné :","o":["Appuie vers les pieds pendant que le patient fait le pont","Tire le patient par les épaules vers la tête du lit","Tire le drap seul, sans aide du patient","Soulève le bassin pendant que le patient pousse"],"r":0,"e":"L'opération se répète jusqu'à la tête de lit. Le patient remonte, genoux fléchis et pieds appuyés.","s":0},{"q":"Pour rouler un patient avec assistance, le kiné place ses mains :","o":["Une sur la ceinture scapulaire, l'autre sur la pelvienne","Les deux sur les épaules, pour tirer vers soi","Les deux sur le bassin, pour pousser vers l'avant","Une sous les genoux, l'autre derrière la nuque du patient"],"r":0,"e":"Le patient a les membres inférieurs fléchis et les pieds appuyés. Le roulement se fait en bloc.","s":0},{"q":"Pour rouler sans assistance, le patient :","o":["Écarte les bras, fléchit les jambes et roule paumes jointes","Tire sur la barrière du lit, en gardant les jambes bien tendues","Pousse avec la tête contre l'oreiller pour pivoter","Utilise le drap pour se tirer vers le bord"],"r":0,"e":"Ce schéma exploite l'enroulement des ceintures pour amorcer le retournement.","s":0},{"q":"Lors du passage assis avec assistance, le membre supérieur proximal du kiné :","o":["Soutient la tête, assurant le contrôle scapulaire","Amène les membres inférieurs hors de la table","Tire sur le bras du patient, en gardant le coude tendu","Reste libre, prêt à rattraper le patient"],"r":0,"e":"Le membre supérieur distal amène les membres inférieurs hors de la table, créant le mouvement pendulaire.","s":0},{"q":"Pour s'asseoir sans assistance, le patient :","o":["Un bras sous la poitrine, l'autre sur la table pour pousser","Tire sur la barrière du lit, les jambes tendues","Se relève par ses seuls abdominaux, bras croisés","Se retourne d'abord sur le ventre, puis pousse sur les genoux"],"r":0,"e":"Le principe pendulaire reste le même qu'avec assistance. Le membre supérieur infra-latéral est sous la poitrine, le supra-latéral fait un push-up.","s":0},{"q":"Lors du passage debout avec assistance, le kiné soutient les genoux :","o":["Sur leur face latérale externe","Sur leur face antérieure","En poplité","Sur la rotule"],"r":0,"e":"Il soutient aussi le membre supérieur selon la dysfonction, et guide le transfert de poids vers l'avant, l'équilibre et le redressement.","s":0},{"q":"Pour se lever sans assistance, la consigne est :","o":["Mains au bord du lit, se pencher, nez vers les pieds","Pousser sur les bras seuls, le dos bien droit","Se pencher en arrière, puis pousser sur les talons","Tirer sur le kiné, en gardant les bras tendus devant soi"],"r":0,"e":"Le mouvement vers l'avant amène le centre de gravité au-dessus des pieds. On étire ensuite la colonne et les genoux.","s":0},{"q":"L'étape a) du transfert selon le cahier consiste en :","o":["L'évaluation de la pathologie, de la dépendance, de l'alitement","La stratégie, avec le nombre de porteurs et l'itinéraire","La minimisation des risques liés au levage et au transport","Le positionnement final du patient après le transfert"],"r":0,"e":"L'étape b) définit la stratégie : nombre de transporteurs, lieu, type de transfert et itinéraire.","s":0},{"q":"L'étape c) du transfert, minimiser les risques, comprend :","o":["Préparer l'espace, analyser le levage, vérifier les fixations","Évaluer la pathologie, la dépendance et l'alitement du patient","Choisir l'itinéraire et le nombre de transporteurs","Informer le patient du déroulement du transfert"],"r":0,"e":"Les freins du fauteuil font partie des fixations à contrôler. On vérifie aussi la hauteur et la stabilité des surfaces, et on analyse le transport.","s":0},{"q":"En position assise, les points d'appui comprennent :","o":["Omoplates, ischions, sacrum, creux poplités, métatarses","Calcanéums, sacrum, occiput, épineuses et coudes","Oreille, trochanter, condyle et malléole externes","Visage ou front, épaules, épines iliaques et les rotules"],"r":0,"e":"La tubérosité ischiatique est la zone de pression majeure de l'assise prolongée. À l'omoplate, c'est l'épine qui appuie.","s":0},{"q":"Chez un patient partiellement dépendant en décubitus dorsal, l'attention porte particulièrement sur :","o":["La symétrie et l'alignement","La seule protection des talons","Le seul coussin de tête","La rotation de la tête"],"r":0,"e":"L'alignement tête-tronc-membres et la protection des protubérances osseuses restent la base du positionnement.","s":0},{"q":"À quel niveau se règle la poignée de toute aide à la marche ?","o":["Au niveau du grand trochanter","Au niveau de la crête iliaque","Au niveau du coude fléchi à 90°","Au niveau de la taille"],"r":0,"e":"C'est la règle universelle, valable pour toutes les aides.","s":1},{"q":"Quelle flexion de coude le réglage doit-il permettre ?","o":["Environ 25°","Environ 90°","Environ 45°","0°, coude tendu"],"r":0,"e":"Une légère flexion de 25° est la règle constante.","s":1},{"q":"À quelle distance des pieds placer l'embout d'une canne ou d'une béquille ?","o":["10 à 15 cm en avant et en dehors des pieds","Juste devant les orteils, au contact de la chaussure","30 cm en avant, dans l'axe du pied","À l'aplomb du pied, contre la malléole"],"r":0,"e":"Cette règle vaut pour cannes, béquilles canadiennes et axillaires.","s":1},{"q":"Où placer le support thoracique d'une béquille axillaire ?","o":["À environ 10 cm sous l'aisselle","Dans le creux de l'aisselle","À environ 25 cm sous l'aisselle","Sur le haut de l'épaule"],"r":0,"e":"L'appui se fait sur le côté de la cage thoracique, jamais dans le creux axillaire.","s":1},{"q":"Pourquoi le support axillaire ne doit-il pas toucher l'aisselle ?","o":["Pour éviter de comprimer les structures axillaires","Pour éviter la transpiration sous le bras","Pour garder un meilleur équilibre du tronc","Pour faciliter le pliage et le rangement de la béquille"],"r":0,"e":"La compression neuro-vasculaire axillaire est le risque redouté. Nerfs et vaisseaux axillaires risqueraient d'être comprimés.","s":1},{"q":"De quel côté utiliser une aide à la marche unilatérale ?","o":["Du côté opposé à la dysfonction","Du côté de la dysfonction","Du côté dominant","Peu importe"],"r":0,"e":"L'aide du côté opposé maintient une démarche physiologique.","s":1},{"q":"De combien l'aide du côté opposé réduit-elle la charge sur la hanche atteinte ?","o":["Environ 60 %","Environ 20 %","Environ 90 %","Environ 10 %"],"r":0,"e":"Bateni & Maki (2005) : environ 60 % de réduction sur la coxo-fémorale.","s":1},{"q":"À quelle distance sous le coude se règle la sangle d'une béquille canadienne ?","o":["5 cm","10 cm","15 cm","2 cm"],"r":0,"e":"La sangle d'avant-bras se place 5 cm sous le coude.","s":1},{"q":"Comment orienter la poignée d'un trépied ou d'une pyramide ?","o":["Concavité vers le patient, appuis vers l'extérieur","Concavité vers l'extérieur, appuis vers le patient","Concavité vers le patient, appuis vers l'intérieur","Concavité vers l'avant, appuis tournés en arrière"],"r":0,"e":"C'est le réglage propre aux trépieds et pyramides.","s":1},{"q":"Combien de points d'appui compte un trépied ?","o":["Trois","Quatre","Deux","Cinq"],"r":0,"e":"La pyramide en compte quatre.","s":1},{"q":"Chez quelle population le trépied réduit-il le balancement postural ?","o":["Les personnes hémiplégiques","Les personnes amputées","Les personnes âgées sans pathologie","Les sportifs"],"r":0,"e":"Laufer (2003) a montré cet effet chez les hémiplégiques.","s":1},{"q":"Quelle aide offre la plus grande base d'appui parmi les aides mobiles ?","o":["Le déambulateur, à base quadrangulaire","La canne simple, à un seul point","La béquille canadienne, avec appui antébrachial","La béquille axillaire, sous l'aisselle"],"r":0,"e":"Les barres parallèles offrent la sécurité maximale, mais ne sont pas mobiles.","s":1},{"q":"Quel intérêt présente un déambulateur articulé ?","o":["Il facilite la dissociation des ceintures","Il se replie plus vite pour le rangement","Il est plus léger qu'un modèle fixe","Il roule mieux sur les sols irréguliers"],"r":0,"e":"L'articulation permet un schéma de marche plus physiologique.","s":1},{"q":"Quelle aide est la plus efficace pour contrôler l'appui partiel sur le membre lésé ?","o":["La béquille axillaire","La béquille canadienne","Le déambulateur","La canne"],"r":0,"e":"Youdas et al. (2005) : les béquilles axillaires contrôlent mieux le transfert partiel de poids.","s":1},{"q":"Quel effet la canne a-t-elle chez l'hémiparétique ?","o":["Elle réduit le travail du membre inférieur parétique","Elle augmente le travail du membre inférieur parétique","Elle n'a aucun effet mesurable sur l'activité musculaire","Elle inhibe le tibial antérieur et les extenseurs"],"r":0,"e":"Buurke et al. (2005). Elle active aussi les extenseurs du tronc et le tibial antérieur.","s":1},{"q":"Quel MI monte en premier dans un escalier ?","o":["Le membre sain","Le membre lésé","Les deux simultanément","Peu importe"],"r":0,"e":"Moyen mnémotechnique : le bon monte au ciel, le mauvais descend en enfer.","s":1},{"q":"Quel MI descend en premier dans un escalier ?","o":["Le membre lésé, avec les aides","Le membre sain, suivi des deux aides","Les deux membres, en même temps","Peu importe, selon le patient"],"r":0,"e":"Aides et membre lésé descendent d'abord, puis le membre sain.","s":1},{"q":"Quelle marche correspond à un appui NUL sur le membre lésé ?","o":["La marche à 3 points","La marche à 3 points modifiés","La marche à 4 points","La marche à 2 points"],"r":0,"e":"Le membre lésé fait le pas sans toucher le sol.","s":1},{"q":"Quelle marche correspond à un appui PARTIEL sur le membre lésé ?","o":["La marche à 3 points modifiés","La marche à 3 points stricte","La marche à 4 points croisés","La marche semi-pendulaire"],"r":0,"e":"Aides et membre lésé avancent simultanément, avec charge partielle.","s":1},{"q":"Quelle est la séquence de la marche à 4 points ?","o":["Aide D, MI G, aide G, MI D","Aide D, aide G, MI D, MI G","MI D, MI G, aide D, aide G","Aides simultanées puis MI simultanés"],"r":0,"e":"Quatre temps distincts, appui possible sur les deux MI.","s":1},{"q":"Quelle est la séquence de la marche à 2 points ?","o":["Aide G et MI D ensemble, puis aide D et MI G","Aide D puis MI D, ensuite aide G puis enfin MI G","Les deux aides ensemble, puis les deux MI","MI D puis MI G, les aides restant fixes"],"r":0,"e":"Les mouvements croisés simultanés exigent un bon équilibre.","s":1},{"q":"Quelle est la différence entre marche semi-pendulaire et pendulaire ?","o":["En pendulaire, les pieds dépassent la ligne des aides","En pendulaire, les pieds restent derrière les aides","En semi-pendulaire, la marche est plus rapide qu'en pendulaire","En pendulaire, une seule aide est utilisée"],"r":0,"e":"Swing-to : jusqu'à la ligne des aides. Swing-through : au-delà.","s":1},{"q":"Quels prérequis pour les marches pendulaires ?","o":["Bras forts, orthèses aux jambes, deux béquilles canadiennes","Aucun prérequis, la technique convient à tous","Un déambulateur et une aide humaine constante","Une force normale aux deux membres inférieurs, sans aucune orthèse"],"r":0,"e":"Environ 50 % des personnes avec lésion médullaire peuvent marcher.","s":1},{"q":"En quoi consiste le « verrouillage du bassin » de la marche semi-pendulaire ?","o":["Une extension de hanche en bascule postérieure","Une flexion de hanche en bascule antérieure","Une rotation du bassin vers le côté porteur","Une inclinaison latérale du bassin vers le côté sain"],"r":0,"e":"Ce verrouillage stabilise la position avant chaque propulsion.","s":1},{"q":"Quel est le diamètre des grandes roues d'un fauteuil roulant ?","o":["61 cm","45 cm","20 cm","75 cm"],"r":0,"e":"Les roues libres, elles, mesurent environ 20 cm.","s":1},{"q":"Quel est le diamètre des roues libres d'un fauteuil roulant ?","o":["Environ 20 cm","Environ 61 cm","Environ 40 cm","Environ 10 cm"],"r":0,"e":"Ce sont elles qui confèrent au fauteuil ses caractéristiques de braquage.","s":1},{"q":"À quelle distance du sol régler les repose-pieds ?","o":["Environ 5 cm","Environ 15 cm","Environ 2 cm","Environ 20 cm"],"r":0,"e":"Ils favorisent aussi une position neutre de la tibio-tarsienne.","s":1},{"q":"À quelle distance de la région poplitée doit s'arrêter l'assise ?","o":["5 à 7 cm","1 à 2 cm","10 à 12 cm","Elle doit toucher le creux poplité"],"r":0,"e":"La profondeur ne doit pas comprimer la région poplitée.","s":1},{"q":"Quelle hauteur de dossier pour un patient tétraplégique ?","o":["Un dossier haut, pour mieux soutenir le tronc","Un dossier bas, pour plus de liberté","Aucun dossier, pour travailler l'équilibre","Un dossier inclinable, et lui seul"],"r":0,"e":"Le dossier bas convient aux paraplégiques ayant le contrôle du tronc.","s":1},{"q":"Quels bénéfices apporte le standing frame ?","o":["Plus d'autonomie, moins de perte osseuse et de spasticité","Un renforcement direct des muscles des jambes","Un remplacement complet de la marche au quotidien","Une amélioration de la circulation sanguine, et elle seule"],"r":0,"e":"Il évite aussi les altérations de la mobilité articulaire (Harvey, 2008). Il améliore aussi l'estime de soi.","s":1},{"q":"Le déambulateur présente une base d'appui :","o":["Quadrangulaire, la plus large des aides","Triangulaire, comme celle du trépied","Ponctuelle, comme celle de la canne","Linéaire, comme celle des béquilles"],"r":0,"e":"Il est bilatéral, réglable en hauteur et parfois en largeur, et peut être articulé pour faciliter la dissociation des ceintures.","s":1},{"q":"La pyramide se distingue du trépied par :","o":["Ses 4 points d'appui, contre 3","Sa base plus petite, à 2 points d'appui","Son usage bilatéral, avec 2 aides","L'absence de poignée, et ses 3 pieds"],"r":0,"e":"Dans les deux cas, la concavité de la poignée est tournée vers le patient et les points d'appui vers l'extérieur.","s":1},{"q":"Selon Laufer (2003), le trépied :","o":["Réduit le balancement postural de l'hémiplégique","Augmente la vitesse de marche de l'hémiplégique","Diminue la dépense énergétique pendant la marche","Supprime la douleur à l'appui du membre atteint"],"r":0,"e":"Buurke et al. (2005) montrent de leur côté que la canne diminue le travail musculaire du membre inférieur chez l'hémiparétique.","s":1},{"q":"Selon Youdas et al. (2005), la béquille axillaire est :","o":["Plus efficace que les autres aides pour l'appui partiel","Moins efficace que la canadienne pour l'appui partiel","Équivalente au déambulateur pour l'appui partiel","Contre-indiquée en cas d'appui partiel prescrit"],"r":0,"e":"Son support thoracique se place 10 cm sous l'aisselle, en appui sur le côté de la cage thoracique. Elle surpasse les béquilles canadiennes et le déambulateur sur ce point.","s":1},{"q":"Les barres parallèles offrent :","o":["Une base d'appui maximale et une sécurité maximale","Une base petite, réservée aux patients autonomes","Un usage unilatéral, d'un seul côté du patient","Une hauteur fixe, sans aucun réglage possible"],"r":0,"e":"Elles permettent aussi l'entraînement aux transferts assis-debout et sont fixes ou mobiles, réglables en hauteur et en largeur. Cette sécurité vaut pour le patient comme pour le kiné.","s":1},{"q":"Une canne en bois se distingue d'une canne en aluminium par le fait :","o":["Qu'elle est faite sur mesure, non réglable","Qu'elle est réglable en hauteur, par crans successifs","Qu'elle est plus légère, donc plus maniable","Qu'elle a trois points d'appui, au lieu d'un"],"r":0,"e":"Les poignées peuvent être anatomiques, rectilignes ou circulaires. La canne en aluminium, elle, est réglable.","s":1},{"q":"Une plus grande base d'appui permet :","o":["De garder plus longtemps le centre de gravité dans la base","D'augmenter la vitesse de marche du patient","De réduire nettement le coût énergétique du cycle de marche","D'augmenter la longueur du pas à chaque cycle"],"r":0,"e":"C'est le principe qui hiérarchise les aides, du déambulateur à la canne. Le centre de gravité reste dans la base sur une plus grande partie du cycle de marche.","s":1},{"q":"Les accoudoirs du fauteuil roulant se règlent pour :","o":["Un repos des bras coudes à 90°, utile aux push-up","Des coudes en extension, pour faciliter la propulsion","Un appui axillaire, comme sur une béquille","Une propulsion plus efficace, coudes à 45°"],"r":0,"e":"Ils sont amovibles, ce qui est nécessaire lors des transferts. Ils favorisent aussi une bonne posture du tronc.","s":1},{"q":"Les protections latérales du fauteuil roulant se règlent :","o":["À 2-3 cm des hanches","Au contact des hanches","À 10 cm","Sans réglage"],"r":0,"e":"L'assise se règle, elle, avec un angle de 90° aux hanches et aux genoux.","s":1},{"q":"La hauteur du dossier d'un fauteuil roulant se situe :","o":["10 cm sous l'aisselle, près de l'angle de la scapula","Au niveau des épaules, pour soutenir la tête","À mi-dos, quel que soit le niveau de lésion","Au niveau des crêtes iliaques, soit 20 cm plus bas"],"r":0,"e":"Un dossier haut convient à la tétraplégie, un dossier bas à la paraplégie avec contrôle du tronc. Soit 2,5 à 5 cm de l'angle inférieur de la scapula.","s":1},{"q":"Les jantes propulsives se situent :","o":["À l'extérieur des grandes roues, pour le patient","À l'intérieur des grandes roues, pour le patient","Sur les roues libres avant, pour le transporteur","Sur le châssis arrière, pour le transporteur"],"r":0,"e":"Les poignées permettent, elles, la conduite par un transporteur.","s":1},{"q":"Les dispositifs anti-chute du fauteuil roulant :","o":["Sont des extensions arrière, contre la bascule en arrière","Sont des butées avant, placées sous les repose-pieds du fauteuil","Bloquent les roues dès que le fauteuil est en pente","Remplacent les freins lors des transferts au lit"],"r":0,"e":"Le châssis peut être articulé en X, donc pliable, ou rigide. Ils facilitent aussi le soulèvement de l'avant aux trottoirs.","s":1},{"q":"L'orthèse genou-tibia-pied stabilise :","o":["Le genou en extension, la cheville en flexion dorsale","Le genou en flexion, la cheville en flexion plantaire","La hanche en extension, le genou restant libre","Le bassin, par une stabilisation latérale en appui"],"r":0,"e":"L'orthèse hanche-genou-tibia-pied y ajoute la stabilisation latérale du bassin, essentielle en phase d'appui selon Harvey (2008). La flexion dorsale est légère, de 5 à 10°.","s":1},{"q":"Dans la marche à 4 points, les aides se placent :","o":["À environ 15 cm en avant et en dehors de chaque pied","Au contact des pieds, à leur bord externe","À environ 30 cm en avant, dans l'axe des pieds","Derrière les pieds, à environ 10 cm du talon"],"r":0,"e":"La séquence est aide droite, membre inférieur gauche, aide gauche, membre inférieur droit.","s":1},{"q":"Dans la marche à 3 points, le membre lésé :","o":["Fait le pas sans toucher le sol","Supporte une charge partielle","Reste immobile","Supporte tout le poids"],"r":0,"e":"Le poids est porté par les aides et le membre sain, qui dépasse ensuite la ligne des aides.","s":1},{"q":"Dans la marche à 3 points modifiés, les aides avancent :","o":["En même temps que le membre lésé","Juste avant le membre lésé","Juste après le membre lésé","En alternance avec le membre sain"],"r":0,"e":"Le transfert se fait ensuite sur les aides et le membre lésé, en charge partielle, avant que le membre sain ne dépasse les aides.","s":1},{"q":"La marche à 2 points est indiquée chez un patient :","o":["Ayant un bon équilibre et un appui bilatéral","N'ayant aucun appui possible sur un membre","Autorisé seulement à un appui partiel du membre lésé","Totalement dépendant, même pour se lever"],"r":0,"e":"Aide gauche et membre inférieur droit avancent simultanément, puis aide droite et membre inférieur gauche.","s":1},{"q":"Le standing frame apporte notamment :","o":["Plus d'indépendance, de fonctionnalité et d'estime de soi","Une hausse de la spasticité des membres inférieurs","Une perte de densité osseuse, liée à l'appui","Une raideur articulaire, compensée ensuite par la verticalité"],"r":0,"e":"Il limite la perte de densité minérale osseuse, diminue la spasticité et évite les altérations de mobilité articulaire.","s":1},{"q":"Les freins du fauteuil roulant assurent :","o":["L'immobilisation et la stabilisation","La propulsion et le ralentissement","Le braquage et le maintien de cap","L'inclinaison et la bascule arrière"],"r":0,"e":"Les roues libres, d'environ 20 cm, confèrent quant à elles le braquage.","s":1},{"q":"Les repose-pieds se règlent avec :","o":["Cheville et pieds en position neutre, à 5 cm du sol","Les pieds en flexion plantaire, à 10 cm du sol","Les pieds en contact direct avec le sol","Les chevilles en flexion dorsale maximale, à 5 cm du sol"],"r":0,"e":"Ils sont fixes ou amovibles, ce qui conditionne la faisabilité des transferts.","s":1},{"q":"Comment placer le membre supérieur du côté vers lequel la tête est tournée, en décubitus ventral ?","o":["Bras en abduction, coude fléchi à 90°","Bras en adduction, coude tendu le long du corps","Bras le long du corps, coude à 45°","Main sous le thorax, coude fléchi"],"r":0,"e":"Le MS opposé, lui, est en légère abduction, rotation interne et coude en extension.","s":2},{"q":"Comment placer le membre supérieur du côté opposé, en décubitus ventral ?","o":["Légère abduction, rotation interne, coude tendu","Abduction marquée, coude fléchi à 90°","Le long du corps, coude fléchi, paume en haut","Au-dessus de la tête, en rotation externe"],"r":0,"e":"Les deux MS sont positionnés différemment selon l'orientation de la tête.","s":2},{"q":"Comment positionner la tibio-tarsienne en décubitus ventral ?","o":["En position neutre, sur un oreiller","En flexion plantaire, sans support","En flexion dorsale, contre la table","En éversion, sur le bord de la table"],"r":0,"e":"L'oreiller sous la cheville évite l'appui des orteils et l'équin.","s":2},{"q":"Comment placer le visage du patient en décubitus ventral ?","o":["Latéralisé","Face contre le matelas","En hyperextension","Sur un coussin en creux"],"r":0,"e":"Le visage est tourné d'un côté, ce qui conditionne la position des MS.","s":2},{"q":"Quels sont les points d'appui à protéger en décubitus ventral ?","o":["Joue, épaules, seins, crêtes iliaques, rotules et pieds","Occiput, omoplates, coudes, sacrum et calcanéums","Oreille, acromion, trochanter, condyle et malléole","Ischions, sacrum, creux poplités, métatarses et talons"],"r":0,"e":"Ce sont les reliefs de la face antérieure du corps. S'y ajoutent les organes génitaux ; la joue peut être remplacée par l'oreille, et le pied appuie par son dos.","s":2},{"q":"De combien relève-t-on la tête de lit en position Fowler / semi-Fowler ?","o":["Entre 30° et 60°","Entre 10° et 20°","Entre 70° et 90°","À plat"],"r":0,"e":"Fowler ≈ 45-60°, semi-Fowler ≈ 30°.","s":2},{"q":"À quel angle correspond la position semi-Fowler ?","o":["Environ 30°","Environ 60°","Environ 90°","Environ 15°"],"r":0,"e":"Fowler est à 45-60°, semi-Fowler à 30°.","s":2},{"q":"Comment placer le poignet en position Fowler ?","o":["En pronation et extension","En supination et flexion","En position neutre stricte","En déviation ulnaire"],"r":0,"e":"Légère flexion d'épaule et de coude, pronation et extension du poignet.","s":2},{"q":"Comment placer la coxo-fémorale en position Fowler ?","o":["En flexion et légère abduction","En extension complète","En adduction stricte","En rotation externe maximale"],"r":0,"e":"Hanches en flexion et légère abduction, genoux en flexion.","s":2},{"q":"Combien d'objectifs poursuit la mobilité précoce au lit ?","o":["Trois","Cinq","Deux","Six"],"r":0,"e":"Schémas de mouvement, image corporelle, indépendance et autonomie.","s":2},{"q":"Que doit-on toujours faire avant d'aider le patient ?","o":["Attendre sa réponse motrice","Le mobiliser rapidement","Lui demander de se détendre complètement","Immobiliser le segment"],"r":0,"e":"L'aide dépend des capacités du patient : on attend toujours sa réponse motrice.","s":2},{"q":"Combien de principes de sécurité sont listés pour la mobilité précoce ?","o":["Huit","Cinq","Six","Dix"],"r":0,"e":"De « ne pas traîner » à « demander de l'aide lorsque c'est nécessaire ».","s":2},{"q":"Quel est le premier principe de sécurité ?","o":["Ne pas traîner le patient","Ne pas tirer sur les articulations","Éviter les amplitudes extrêmes","Promouvoir un bon alignement"],"r":0,"e":"Les deux premiers interdits sont : ne pas traîner, ne pas tirer sur les articulations.","s":2},{"q":"Quel principe concerne la posture du kinésithérapeute ?","o":["Adopter une posture adaptée et optimiser sa biomécanique","Rester debout, le dos droit et les jambes bien tendues","Se pencher en avant pour être au plus près du patient","Garder la même posture, quelle que soit la manœuvre"],"r":0,"e":"Il tire profit de son positionnement et de son poids corporel.","s":2},{"q":"Quelle place donner à la participation du patient ?","o":["Permettre la participation maximale","La limiter pour aller plus vite","L'interdire pour éviter les erreurs","La réserver aux patients autonomes"],"r":0,"e":"La participation maximale est un principe de sécurité explicite.","s":2},{"q":"Comment réajuster un patient dans le lit à deux personnes ?","o":["De part et d'autre du lit, avec un drap de glissement","Du même côté du lit, l'un tire et l'autre pousse","De chaque côté, en soulevant par les aisselles","Du même côté, en faisant rouler le patient vers soi"],"r":0,"e":"Le drap de glissement ou l'alèse et la coordination sont essentiels. Le mouvement des deux intervenants est synchronisé.","s":2},{"q":"Comment réajuster un patient dans le lit à une seule personne ?","o":["Par étapes, haut puis bas du corps, avec son poids","D'un seul coup, en tirant sur le drap sous le bassin","En soulevant tout le corps, bras sous le tronc","En inclinant le lit, tête vers le bas"],"r":0,"e":"Le fractionnement évite tout arrachement. On procède segment supérieur puis inférieur, sans arrachement.","s":2},{"q":"Comment préparer un patient totalement dépendant avant de le rouler ?","o":["Bras croisé sur le thorax, genou fléchi","Bras le long du corps, jambes tendues","Bras au-dessus de la tête","Jambes croisées"],"r":0,"e":"La préparation des segments facilite le roulement en bloc.","s":2},{"q":"Quel principe respecter pendant le roulement ?","o":["L'alignement tête-tronc-membres","La vitesse d'exécution","La flexion cervicale maximale","La rotation isolée du bassin"],"r":0,"e":"Le roulement se fait en bloc, alignement préservé.","s":2},{"q":"Quel est le rôle du kinésithérapeute pour rouler un patient partiellement dépendant ?","o":["Faciliter et guider, en laissant le patient initier","Réaliser tout le mouvement, sans aide du patient","Immobiliser le patient, pour éviter la chute","Ne pas intervenir, sauf en cas de chute"],"r":0,"e":"L'aide se réduit à mesure que le patient récupère.","s":2},{"q":"Quel est le principe biomécanique du passage couché → assis ?","o":["Le bras d'appui et les jambes hors du lit en contrepoids","La traction du kiné sur les épaules du patient","La poussée du kiné sur le bassin, vers l'avant","L'inclinaison du lit, qui relève peu à peu le tronc du patient"],"r":0,"e":"Le contrepoids des jambes facilite le redressement du tronc.","s":2},{"q":"Depuis quelle position se fait le passage à la position assise ?","o":["Depuis le décubitus latéral","Depuis le décubitus dorsal strict","Depuis le décubitus ventral","Depuis la position debout"],"r":0,"e":"La transition va du décubitus latéral vers l'assis au bord du lit.","s":2},{"q":"Que contrôle le kinésithérapeute lors du passage à la position orthostatique avec assistance ?","o":["Les genoux et le bassin","La tête et les épaules","Les pieds uniquement","Les mains"],"r":0,"e":"L'appui manuel porte sur les genoux et le bassin.","s":2},{"q":"Quel est l'enchaînement logique de la mobilité précoce ?","o":["Réajuster dans le lit → rouler → s'asseoir → debout","S'asseoir → rouler → debout → réajuster dans le lit","Rouler → réajuster dans le lit → s'asseoir → debout","Rouler → debout → s'asseoir → réajuster dans le lit"],"r":0,"e":"Chaque étape suppose que la précédente est acquise.","s":2},{"q":"Quel objectif cognitif poursuit la mobilité précoce ?","o":["Augmenter la conscience de l'image corporelle","Améliorer la mémoire de travail du patient","Réduire l'anxiété liée à l'alitement","Stimuler le langage par des consignes verbales"],"r":0,"e":"C'est le deuxième des trois objectifs.","s":2},{"q":"Que promeut la mobilité précoce sur le plan fonctionnel ?","o":["L'indépendance et l'autonomie du patient","La dépendance encadrée par l'équipe soignante","Le repos strict au lit du patient","L'immobilisation protectrice des membres"],"r":0,"e":"C'est le troisième objectif de la mobilité précoce au lit.","s":2},{"q":"Quelle amplitude faut-il éviter pendant la mobilité précoce ?","o":["Les amplitudes articulaires extrêmes","Les amplitudes moyennes","Les amplitudes de course interne","Toute amplitude"],"r":0,"e":"Troisième principe de sécurité.","s":2},{"q":"Quand le kinésithérapeute doit-il demander de l'aide ?","o":["Dès que c'est nécessaire, par principe de sécurité","Jamais, car cela nuirait à sa crédibilité","Seulement pour les patients de plus de 100 kg","Seulement en réanimation ou en soins intensifs"],"r":0,"e":"C'est le huitième principe de sécurité.","s":2},{"q":"Quel programme suit la deuxième partie de ce cours ?","o":["Objectifs, précautions, réajuster, rouler, s'asseoir, debout","Escarres, décubitus, positionnements et transferts","Marche, escaliers, aides techniques et fauteuil roulant","Bilan, diagnostic, objectifs, traitement et réévaluation finale"],"r":0,"e":"C'est le programme annoncé de la mobilité précoce au lit.","s":2},{"q":"Comment doit être maintenue la tibio-tarsienne en position Fowler ?","o":["Soutenue et en position neutre","Libre en flexion plantaire","En appui sur le talon uniquement","En flexion dorsale forcée"],"r":0,"e":"Comme dans les autres décubitus, la neutralité est la règle.","s":2},{"q":"En décubitus ventral, le membre supérieur du côté opposé au regard se place :","o":["En légère abduction, rotation interne, coude tendu","En abduction, coude fléchi à 90°, paume en bas","Le long du corps, en rotation externe, coude fléchi","En rotation externe, coude fléchi sous le front"],"r":0,"e":"Le membre supérieur du côté vers lequel la tête est tournée se place, lui, en abduction avec coude fléchi à 90°.","s":2},{"q":"En décubitus ventral, les zones de pression à protéger sont :","o":["Joue, épaules, seins, crêtes iliaques, rotules et pieds","Sacrum, calcanéums, occiput et coudes","Trochanter, malléole externe et acromion","Occiput, épines scapulaires, sacrum, coudes et calcanéums"],"r":0,"e":"La tibio-tarsienne y est placée en position neutre, posée sur un oreiller. S'y ajoutent les organes génitaux ; au pied, c'est le dos du pied ou les orteils.","s":2},{"q":"La position Fowler correspond à un relèvement d'environ :","o":["30°","45 à 60°","20°","75°"],"r":1,"e":"La position semi-Fowler correspond à environ 30° ; la fourchette générale va de 30 à 60°.","s":2},{"q":"En position Fowler, l'avant-bras et le poignet sont placés :","o":["En pronation, avec extension du poignet","En supination, avec flexion complète du poignet","En pronation, avec flexion du poignet","En position neutre, poignet libre"],"r":0,"e":"L'épaule et le coude sont en légère flexion.","s":2},{"q":"En position Fowler, la coxo-fémorale est placée :","o":["En flexion, avec légère abduction","En extension, avec rotation externe libre","En flexion, avec rotation interne","En extension, avec adduction"],"r":0,"e":"Les genoux sont en flexion et la tibio-tarsienne soutenue en position neutre.","s":2},{"q":"Les trois objectifs de la mobilité précoce sont :","o":["Mouvements physiologiques, image corporelle, indépendance","Renforcer, assouplir et mobiliser les articulations","Prévenir, traiter et éduquer le patient et l'aidant","Stimuler, relaxer et drainer les tissus du patient alité"],"r":0,"e":"L'aide apportée dépend des capacités du patient, et il faut toujours attendre sa réponse motrice. Il s'agit de faciliter les schémas physiologiques, d'augmenter la conscience de l'image corporelle et de promouvoir l'indépendance.","s":2},{"q":"Parmi les 8 principes de sécurité, les deux premiers sont :","o":["Ne pas traîner le patient et ne pas tirer sur les articulations","Éviter les amplitudes extrêmes et promouvoir l'alignement","Permettre la participation et adopter une bonne posture","Utiliser sa biomécanique et demander de l'aide"],"r":0,"e":"Les six autres portent sur les amplitudes extrêmes, l'alignement, la participation, la posture du kiné, sa biomécanique et le recours à l'aide.","s":2},{"q":"Le principe de sécurité concernant le kinésithérapeute porte sur :","o":["Une posture adaptée et une biomécanique optimisée","Sa seule force, quelle que soit la manœuvre","Sa taille, qui fixe la hauteur du lit et des prises","Son expérience, qui dispense des règles de base"],"r":0,"e":"Demander de l'aide lorsque c'est nécessaire complète ces principes. Il utilise son positionnement et son poids corporel.","s":2},{"q":"Pour réajuster un patient dans le lit à deux personnes :","o":["De part et d'autre du lit, avec un drap, en synchronie","Du même côté du lit, l'un tirant et l'autre poussant le drap","De chaque côté, en tirant le patient par les épaules","De chaque côté, en soulevant le patient sans drap"],"r":0,"e":"Seul, on procède par étapes successives, segment supérieur puis inférieur, en utilisant le poids du corps et en évitant tout arrachement. Le drap peut être un drap de glissement ou une alèse ; le mouvement est coordonné.","s":2},{"q":"Pour rouler un patient totalement dépendant, la préparation consiste à :","o":["Croiser le bras sur le thorax et fléchir le genou","Étendre les membres et les plaquer le long du corps","Placer les deux bras en abduction, genoux tendus","Surélever la tête et fléchir les deux hanches"],"r":0,"e":"Le kiné assure tout le mouvement, en respectant l'alignement tête-tronc-membres.","s":2},{"q":"Pour rouler un patient partiellement dépendant, le kiné :","o":["Facilite et guide, en laissant le patient initier","Réalise tout le mouvement, à la place du patient","Reste passif, en surveillant seulement","Utilise un drap pour tirer le patient vers le côté"],"r":0,"e":"Le degré d'aide se réduit à mesure que le patient récupère.","s":2},{"q":"Le principe biomécanique du passage couché-assis repose sur :","o":["Les bras d'appui et les jambes servant de contrepoids","La seule force des abdominaux du patient","Une traction du patient sur la barrière du lit","Une poussée du kiné dans le dos du patient vers l'avant"],"r":0,"e":"La transition se fait depuis le décubitus latéral vers la position assise au bord du lit.","s":2},{"q":"Lors du passage en position orthostatique avec assistance, le kiné contrôle :","o":["Les genoux et le bassin, par un appui manuel","La tête, par une prise occipitale","Les épaules, par une traction vers l'avant et le haut","Les pieds, par un blocage au sol"],"r":0,"e":"En version autonome, son rôle se limite à la surveillance et à la sécurisation.","s":2},{"q":"L'enchaînement logique de la mobilité précoce est :","o":["Réajuster, rouler, s'asseoir, se lever","Se lever, s'asseoir, rouler, réajuster","Rouler, se lever, s'asseoir, réajuster dans le lit","S'asseoir, rouler, réajuster, se lever"],"r":0,"e":"Chaque étape suppose que la précédente soit acquise.","s":2},{"q":"Combien de temps de pression prolongée suffit à créer une escarre ?","o":["2 à 3 heures","30 minutes","8 heures","24 heures"],"r":0,"e":"C'est la cause n°1 : le stress mécanique prolongé de 2 à 3 heures.","s":3},{"q":"À quelle fréquence changer le décubitus en prévention des escarres ?","o":["Toutes les 2 heures","Toutes les 6 heures","Une fois par jour","Toutes les 30 minutes"],"r":0,"e":"Le changement de décubitus toutes les 2 heures est la mesure phare.","s":3},{"q":"Quelles sont les localisations les plus fréquentes d'escarre ?","o":["Sacrum, calcanéum, coude, grand trochanter","Genou, épaule, poignet, cheville","Crâne, dos, fesses, pieds","Rotule, sternum, clavicule, mandibule"],"r":0,"e":"Ce sont les quatre sites cités dans le cours.","s":3},{"q":"Comment définit-on une escarre ?","o":["Une nécrose locale, le tissu étant comprimé contre l'os","Une infection cutanée superficielle, souvent bactérienne","Une réaction allergique de contact, liée aux draps","Une brûlure du second degré, liée au frottement des draps"],"r":0,"e":"La définition insiste sur la compression entre relief osseux et surface dure. Le tissu est comprimé entre une proéminence osseuse et une surface dure.","s":3},{"q":"Quels sont les trois mécanismes lésionnels de l'escarre ?","o":["Contact, pression et/ou friction","Chaleur, froid et pression","Infection, ischémie et allergie","Traction, torsion et cisaillement"],"r":0,"e":"Le mécanisme s'ajoute au manque d'irrigation sanguine.","s":3},{"q":"Quel facteur cutané lié à l'âge augmente le risque d'escarre ?","o":["La peau devient plus fine et fragile","La peau devient plus épaisse","La peau devient plus grasse et plus humide","La pilosité de la peau augmente"],"r":0,"e":"L'âge est un des trois facteurs de risque cités.","s":3},{"q":"Quels fluides favorisent l'escarre par contact ?","o":["Sueur, sang, urine et selles","Urine seule, sans les autres","Sérum, eau de toilette et crèmes","Sueur seule, sans les autres"],"r":0,"e":"Le contact avec ces fluides est une cause explicite.","s":3},{"q":"Qu'est-ce qui, dans les vêtements et les draps, favorise l'escarre ?","o":["Les plis, par friction","La couleur, par absorption de chaleur","La matière synthétique, seule","Le poids, par écrasement"],"r":0,"e":"La friction due aux plis est une cause listée.","s":3},{"q":"Que caractérise le grade I d'escarre ?","o":["Un érythème non blanchissable sur peau intacte","Une plaie avec destruction partielle de l'épiderme","Un cratère avec nécrose du tissu sous-cutané","Une atteinte musculaire, osseuse ou tendineuse"],"r":0,"e":"La peau est encore intacte, mais l'érythème ne blanchit pas à la pression.","s":3},{"q":"Que caractérise le grade II d'escarre ?","o":["Une destruction partielle de l'épiderme ou du derme","Un érythème non blanchissable sur peau intacte","Une nécrose du tissu sous-cutané, formant un cratère profond","Une lésion osseuse ou des structures de soutien"],"r":0,"e":"Grade II : plaie, peau rouge, œdématiée et douloureuse. Elle peut toucher l'épiderme, le derme ou les deux.","s":3},{"q":"Que caractérise le grade III d'escarre ?","o":["Une destruction totale de la peau, avec nécrose sous-cutanée","Une destruction partielle de l'épiderme ou du derme","Un érythème non blanchissable sur peau intacte","Une atteinte des muscles et des os, avec ou sans nécrose cutanée"],"r":0,"e":"Grade III : cratère, susceptible d'infection.","s":3},{"q":"Que caractérise le grade IV d'escarre ?","o":["Une destruction étendue, jusqu'au muscle ou à l'os","Une destruction totale de la peau, sans atteinte plus profonde","Un cratère superficiel, sans nécrose sous-cutanée","Un érythème douloureux, sur une peau intacte"],"r":0,"e":"Le grade IV atteint les structures profondes, avec ou sans destruction totale de la peau. Les structures de soutien peuvent aussi être atteintes.","s":3},{"q":"À partir de quel grade parle-t-on de « cratère » ?","o":["Le grade III","Le grade I","Le grade II","Le grade IV uniquement"],"r":0,"e":"Le cratère apparaît au grade III, avec nécrose sous-cutanée.","s":3},{"q":"Quelles amplitudes privilégier en décubitus dorsal ?","o":["Les amplitudes d'extension","Les amplitudes de flexion","Les rotations","Les abductions maximales"],"r":0,"e":"C'est le piège d'examen : DD = extension, DL = flexion.","s":3},{"q":"Quelles amplitudes privilégier en décubitus latéral ?","o":["Les amplitudes de flexion","Les amplitudes d'extension","Les rotations externes","Les adductions"],"r":0,"e":"En DL, les membres inférieurs sont en flexion avec un oreiller entre les genoux.","s":3},{"q":"Comment placer les membres supérieurs en décubitus dorsal ?","o":["Légèrement abduits, en rotation externe","En adduction, en rotation interne","Croisés sur le thorax, coudes fléchis","Au-dessus de la tête, coudes tendus"],"r":0,"e":"Légère abduction et rotation externe, main en position fonctionnelle.","s":3},{"q":"Comment placer les membres inférieurs en décubitus dorsal ?","o":["Légèrement abduits et surélevés","En adduction stricte, à plat","Croisés, l'un sur l'autre, sans coussin","En rotation interne, à plat"],"r":0,"e":"Légère abduction et surélévation, tibio-tarsienne en position neutre.","s":3},{"q":"Où placer l'oreiller au niveau des membres inférieurs en décubitus latéral ?","o":["Entre les genoux","Sous les talons","Sous le bassin","Entre les chevilles uniquement"],"r":0,"e":"Les MI sont en flexion avec un oreiller entre les genoux.","s":3},{"q":"Comment placer l'épaule infra-latérale en décubitus latéral ?","o":["Légèrement antériorisée","Légèrement postériorisée","En rotation interne maximale","En abduction à 90°"],"r":0,"e":"L'antériorisation évite la compression de l'épaule du dessous.","s":3},{"q":"Où placer la main infra-latérale en décubitus latéral ?","o":["Appuyée sur l'oreiller de la tête","Glissée sous le bassin du patient","Le long du corps, paume en bas","Posée sur le thorax, coude fléchi"],"r":0,"e":"Elle repose sur l'oreiller de la tête, en position fonctionnelle.","s":3},{"q":"Qu'ajoute-t-on chez le patient partiellement dépendant en décubitus dorsal ?","o":["Maintenir la symétrie entre segments et hémicorps","Une contention douce des membres atteints","Un matelas plus ferme, pour mieux stabiliser le bassin","Une immobilisation stricte des quatre membres"],"r":0,"e":"La symétrie devient un point d'attention supplémentaire.","s":3},{"q":"Combien de variantes existent pour le décubitus latéral sur le côté atteint ?","o":["Trois","Deux","Une","Quatre"],"r":0,"e":"Trois variantes, plus un positionnement spécifique sur le côté non atteint.","s":3},{"q":"Quels sont les points d'appui à protéger en décubitus dorsal ?","o":["Occiput, épines scapulaires, coudes, sacrum, calcanéums","Oreille, acromion, trochanter, condyle et malléole externes","Joue, seins, crêtes iliaques, rotules et dos du pied","Ischions, sacrum, creux poplités et métatarses"],"r":0,"e":"Le décubitus latéral concerne oreille, acromion, trochanter, condyle et malléole externes.","s":3},{"q":"Quels sont les points d'appui à protéger en décubitus latéral ?","o":["Oreille, acromion, trochanter, condyle et malléole externes","Occiput, épines scapulaires, coudes, sacrum et calcanéums","Joue, épaules, seins, crêtes iliaques, rotules et dos du pied","Ischions, sacrum, creux poplités et métatarses"],"r":0,"e":"Ce sont les reliefs latéraux du corps. Il s'agit du grand trochanter et du condyle fémoral externe.","s":3},{"q":"Combien d'objectifs l'intervention de positionnement poursuit-elle ?","o":["Sept","Cinq","Quatre","Neuf"],"r":0,"e":"Quatre préventions, plus mouvement physiologique, lever précoce et éducation.","s":3},{"q":"Quel objectif concerne l'entourage du patient ?","o":["L'éducation du patient et de l'aidant","La formation continue des médecins du service","L'information de l'administration","La visite quotidienne de la famille"],"r":0,"e":"L'éducation du patient et de l'aidant est le septième objectif.","s":3},{"q":"Quel stimulus les positionnements doivent-ils offrir ?","o":["Un stimulus sensoriel et proprioceptif","Un stimulus douloureux et répété","Un stimulus thermique et vibratoire","Aucun stimulus, pour favoriser le repos"],"r":0,"e":"Ils doivent aussi donner la notion du corps comme un tout.","s":3},{"q":"Les positionnements de base sont-ils figés ?","o":["Non, ils s'adaptent aux besoins de chaque patient","Oui, ce sont des protocoles stricts et fixes","Oui, sauf en réanimation et en soins intensifs","Non, mais ils ne changent qu'une seule fois par semaine"],"r":0,"e":"Ils obéissent à un schéma adaptable selon la condition du patient. Ils évoluent avec la progression du patient.","s":3},{"q":"Quelle mesure de prévention repose sur l'autonomie du patient ?","o":["L'auto-contrôle au miroir","Les changements de décubitus","Le matelas anti-escarre","Le lit articulé"],"r":0,"e":"L'auto-contrôle au miroir permet au patient de surveiller ses zones d'appui.","s":3},{"q":"Que faut-il faire de la tibio-tarsienne dans tous les positionnements ?","o":["La maintenir en position neutre","La laisser en flexion plantaire","La maintenir en flexion dorsale maximale","La laisser libre"],"r":0,"e":"La position neutre prévient l'équin ; en DL, elle doit en plus être soutenue.","s":3},{"q":"Parmi les 7 objectifs du positionnement figure :","o":["Faciliter un schéma de mouvement physiologique","Augmenter la force des membres alités","Améliorer la capacité aérobie du patient","Réduire la spasticité des membres atteints"],"r":0,"e":"S'y ajoutent la prévention des altérations musculo-squelettiques, circulatoires, respiratoires et cutanées, le lever précoce et l'éducation. Ce schéma doit être physiologique et fonctionnel.","s":3},{"q":"Parmi les principes directeurs, les positionnements doivent :","o":["Donner la notion du corps comme un tout","Rester identiques d'un jour à l'autre","Immobiliser complètement le patient","Éviter tout stimulus sensoriel"],"r":0,"e":"Ils doivent aussi être confortables et fonctionnels, offrir un stimulus sensoriel et proprioceptif et obéir à un schéma adaptable.","s":3},{"q":"L'escarre se définit comme :","o":["Une mort cellulaire locale, par compression contre un os","Une simple rougeur, qui disparaît sous la pression du doigt","Une infection cutanée, d'origine bactérienne","Une brûlure, liée au frottement prolongé"],"r":0,"e":"Ses trois mécanismes sont le contact, la pression et la friction, avec un manque d'irrigation sanguine. Le tissu est comprimé entre une proéminence osseuse et une surface dure.","s":3},{"q":"La cause numéro 1 d'escarre est :","o":["Un stress mécanique prolongé, de 2 à 3 heures","La dénutrition, au-delà de deux semaines","L'infection locale, au-delà de 48 heures","L'âge avancé, au-delà de 70 ans"],"r":0,"e":"Friction par les plis des vêtements et draps, et contact avec sueur, sang, urine ou selles en sont les autres causes.","s":3},{"q":"Parmi les facteurs de risque d'escarre, le cours cite :","o":["L'alitement, une peau fine liée à l'âge, l'immobilité","La dénutrition seule, sans autre facteur","L'infection seule, sans autre facteur","L'âge seul, quel que soit l'état de la peau du patient"],"r":0,"e":"La paraplégie et la sclérose en plaques sont citées comme exemples d'incapacité à se mobiliser. L'alitement inclut le fauteuil roulant ; l'immobilité est l'incapacité à se mobiliser.","s":3},{"q":"Le grade I d'escarre se caractérise par :","o":["Un érythème non blanchissable sur peau intacte, douloureux","Une destruction partielle de l'épiderme, peau rouge","Un cratère avec nécrose du tissu sous-cutané, souvent infecté","Une lésion osseuse, avec destruction extensive"],"r":0,"e":"Le grade II correspond à une destruction partielle de l'épiderme, du derme ou des deux.","s":3},{"q":"Le grade III d'escarre se caractérise par :","o":["Une destruction totale de la peau, avec un cratère","Un érythème non blanchissable sur peau intacte","Une destruction partielle de l'épiderme ou du derme","Une lésion musculaire et osseuse, avec destruction extensive"],"r":0,"e":"Le grade IV correspond à une destruction extensive, avec lésion musculaire, osseuse ou des structures de soutien. Le tissu sous-cutané est nécrosé et le cratère est susceptible d'infection.","s":3},{"q":"Les points d'appui à protéger en décubitus dorsal sont :","o":["Occiput, épines scapulaires, coudes, sacrum et calcanéums","Oreille, acromion, grand trochanter, condyle et malléole externes","Rotules, épines iliaques, seins et dos du pied","Ischions, sacrum, creux poplités et métatarses"],"r":0,"e":"En décubitus latéral, ce sont l'oreille, l'acromion, le grand trochanter, le condyle fémoral externe, la malléole externe et le bord externe du pied.","s":3},{"q":"En décubitus dorsal, la règle globale est de privilégier :","o":["Les amplitudes d'extension","Les amplitudes de flexion","Les rotations","Les positions neutres uniquement"],"r":0,"e":"En décubitus latéral, ce sont au contraire les amplitudes de flexion qui sont privilégiées.","s":3},{"q":"En décubitus dorsal, les membres inférieurs sont placés :","o":["Légèrement abduits et surélevés","En adduction stricte, à plat","En rotation interne, à plat","En flexion, sur un gros coussin"],"r":0,"e":"Les membres supérieurs sont légèrement abduits en rotation externe, main en position fonctionnelle.","s":3},{"q":"Chez le patient partiellement dépendant en décubitus dorsal, il faut en outre :","o":["Maintenir la symétrie entre segments et hémicorps","Augmenter le nombre de points d'appui","Supprimer les coussins, pour libérer les mouvements","Limiter la mobilisation au strict minimum"],"r":0,"e":"Les principes généraux d'alignement et de protection des proéminences restent par ailleurs identiques.","s":3},{"q":"En décubitus latéral, la main infra-latérale se place :","o":["Appuyée sur l'oreiller de la tête","Glissée sous le tronc, paume vers le haut","Posée le long du corps","Sur l'oreiller du membre supérieur"],"r":0,"e":"L'épaule infra-latérale est légèrement antériorisée et le membre supérieur supra-latéral repose sur un oreiller, en plan horizontal.","s":3},{"q":"Parmi les 10 mesures de prévention des escarres, celle qui repose sur l'autonomie du patient est :","o":["L'auto-contrôle au miroir","Les lits articulés","Le matériel anti-escarre","L'hygiène"],"r":0,"e":"S'y ajoutent les changements de décubitus toutes les 2 heures, le positionnement correct, l'alimentation, les mobilisations active et passive et les soins du linge.","s":3},{"q":"Le changement de décubitus doit se faire :","o":["Toutes les 2 heures","Toutes les 3 heures","Toutes les 6 heures","Une fois par jour"],"r":0,"e":"Ce délai découle du fait que 2 à 3 heures de pression prolongée suffisent à créer une escarre.","s":3},{"q":"Les localisations les plus fréquentes d'escarre sont :","o":["Sacrum, calcanéum, coude et grand trochanter","Occiput, scapula et épines vertébrales","Genou, cheville, rotule et bord interne du pied","Main, poignet et face dorsale des doigts"],"r":0,"e":"Ce sont les proéminences osseuses les plus exposées dans les décubitus habituels.","s":3},{"q":"Les signes d'évolution d'une escarre sont :","o":["Une rougeur qui s'aggrave, puis ulcères, plaies et cratères","Un prurit, puis une desquamation et une cicatrisation","Une desquamation, puis une pâleur et une sécheresse de la peau","Un œdème isolé, qui régresse en quelques heures"],"r":0,"e":"Le cratère apparaît au grade III, avec la destruction totale de la peau.","s":3},{"q":"En décubitus latéral, la tête est placée :","o":["Sur un oreiller, le rachis cervical aligné","Sans oreiller, en appui direct sur le matelas","En rotation, tournée vers le plafond","En extension, sur un petit rouleau"],"r":0,"e":"Les membres inférieurs sont en flexion, avec un coussin entre les genoux.","s":3},{"q":"Les positionnements de base :","o":["S'adaptent à chaque cas, selon la progression du patient","Sont figés, quel que soit l'état du patient","Ne dépendent que de la pathologie, et non du patient","Sont identiques pour tous les patients alités"],"r":0,"e":"C'est le principe du schéma adaptable énoncé dans les principes directeurs.","s":3},{"q":"La tibio-tarsienne doit, dans tous les décubitus, être placée :","o":["En position neutre","En flexion plantaire","En flexion dorsale maximale","En inversion"],"r":0,"e":"Cela prévient l'équin et les zones de pression au talon.","s":3},{"q":"L'objectif du positionnement qui concerne l'entourage du patient est :","o":["L'éducation du patient et de l'aidant","La prévention des lésions cutanées","Le lever précoce, avec l'aide de la famille","La prévention des troubles respiratoires"],"r":0,"e":"Le lever précoce vise, lui, l'indépendance fonctionnelle.","s":3},{"q":"Quand se termine un transfert ?","o":["Au moment où l'on positionne le patient","Quand le patient touche la nouvelle surface","Quand l'équipe se retire","Quand le patient dit être installé"],"r":0,"e":"Le positionnement final fait partie intégrante du transfert.","s":4},{"q":"Quelles sont les quatre exigences d'un transfert ?","o":["Correct, rapide, sûr, charge bien répartie","Lent, sûr, confortable et silencieux","Rapide, économique, sûr et discret","Correct, lent, sûr, réalisé par une seule personne"],"r":0,"e":"La sécurité impose un bon alignement du patient et des transporteurs. La charge doit être répartie équitablement.","s":4},{"q":"Combien de personnes peuvent commander un transfert ?","o":["Une seule, le chef d'équipe","Deux, en alternance","Toutes, à tour de rôle","Aucune, chacun est autonome"],"r":0,"e":"Une seule personne commande, avec des ordres clairs et un décompte.","s":4},{"q":"Quelle règle absolue concerne les contacts manuels ?","o":["Les mains ne soutiennent jamais par le dessus","Les mains soutiennent toujours par le dessus","Les doigts doivent exercer une forte pression","Le contact doit être bref"],"r":0,"e":"C'est la quatrième des six règles des contacts manuels.","s":4},{"q":"Quelle forme doit prendre la main pendant un transfert ?","o":["Une main en coupe, pour épouser le segment","Une main à plat, pour répartir la pression","Une main en pince, pour assurer la prise","Un poing fermé, pour une prise plus solide et stable"],"r":0,"e":"La main en coupe maintient le maximum de contact.","s":4},{"q":"Pourquoi éviter les mains moites ?","o":["Elles font perdre le contact et sont inconfortables","Elles glissent moins bien sur les draps du lit","Elles transmettent plus facilement les infections","Elles refroidissent la peau du patient pendant la prise"],"r":0,"e":"Deux raisons : sécurité et confort.","s":4},{"q":"Que ne doivent pas faire les pulpes des doigts ?","o":["Exercer une pression sur le segment","Toucher directement la peau du patient","Se replier vers la paume de la main","Se croiser avec celles de l'autre main"],"r":0,"e":"La pression des pulpes est douloureuse et inefficace.","s":4},{"q":"Dans un transfert à 3 transporteurs, qui est le chef d'équipe ?","o":["Le poste A, au soutien cervical","Le poste B, au soutien pelvien","Le poste C, aux membres inférieurs","Le plus expérimenté, quel que soit le poste"],"r":0,"e":"Le poste A est tenu par l'élément le plus grand, avec le plus de force.","s":4},{"q":"Quelles zones de prise correspondent au poste A ?","o":["L'occiput et les épines des omoplates","La région lombaire et l'arrière des cuisses","Au-dessus du creux poplité et des malléoles","Le bassin et la face antérieure des cuisses"],"r":0,"e":"Le poste A assure le soutien cervical.","s":4},{"q":"Quelles zones de prise correspondent au poste B ?","o":["La région lombaire et l'arrière des cuisses","L'occiput et les épines des omoplates, en haut","Au-dessus du creux poplité et des malléoles","Les épaules et le bassin, de chaque côté"],"r":0,"e":"Le poste B assure le soutien pelvien.","s":4},{"q":"Quelles zones de prise correspondent au poste C ?","o":["Au-dessus du creux poplité et des malléoles","L'occiput et les épines des omoplates, en haut","La région lombaire et l'arrière des cuisses","Les chevilles et la plante des pieds"],"r":0,"e":"Le poste C soutient les membres inférieurs, tenu par l'élément le plus petit.","s":4},{"q":"Que fait le quatrième transporteur, s'il y en a un ?","o":["Il tracte seulement la tête, en suivant le mouvement","Il soutient les pieds, debout au bout de la table","Il commande la manœuvre, sans toucher le patient","Il prépare le lit d'arrivée, à l'écart du groupe"],"r":0,"e":"C'est la note explicite du cours pour le transfert à 4.","s":4},{"q":"Où placer le patient au début d'un transfert à 3/4 transporteurs ?","o":["Au bord du lit","Au centre du lit","En décubitus latéral","Assis"],"r":0,"e":"Cela raccourcit le levier et sécurise la prise.","s":4},{"q":"Comment le kiné dépose-t-il le patient à la fin du transfert ?","o":["En fléchissant ses membres inférieurs","En se penchant en avant, dos rond","En lâchant progressivement sa prise du patient","En pivotant sur ses deux talons"],"r":0,"e":"La flexion des MI permet une dépose douce.","s":4},{"q":"Quel type de drap est privilégié dans l'alternative au transfert à 3/4 ?","o":["Un drap enroulé, plus résistant","Un drap plié en quatre, plus épais","Un drap fin non enroulé, plus souple à manier","Une alèse jetable, plus hygiénique"],"r":0,"e":"Le drap enroulé, lits parallèles, prise en pronation, drap maintenu en tension.","s":4},{"q":"Pour quels usages la technique australienne est-elle indiquée ?","o":["Longs parcours, escaliers, réajustement, passage au sol","Transferts du lit vers le fauteuil, et eux seuls","Patients totalement dépendants, et eux seuls","Transferts en piscine, en baignoire et en douche, seulement"],"r":0,"e":"Quatre usages sont listés. Elle s'adresse aux patients partiellement dépendants.","s":4},{"q":"Où appuie l'épaule du transporteur dans la technique australienne ?","o":["Sur le côté de la grille costale, sous l'aisselle","Sur l'épaule du patient, contre l'acromion","Dans le creux axillaire, en appui ferme vers le haut","Sur le bassin, contre la crête iliaque"],"r":0,"e":"L'appui sous l'aisselle ne doit jamais comprimer.","s":4},{"q":"Comment se fait l'élévation dans la technique australienne ?","o":["Par les membres inférieurs, de la flexion à l'extension","Par la force des bras, coudes fléchis","Par une traction du tronc vers l'arrière, dos bien tendu","Par un balancier du corps, d'avant en arrière"],"r":0,"e":"C'est le principe biomécanique fondamental.","s":4},{"q":"Où se place le membre supérieur libre pour un réajustement au lit en australienne ?","o":["En appui sur le lit, pour le push-up","Sur l'épaule du patient, pour le guider","Derrière le dos du patient, pour le soutenir","Sur la tête de lit, pour tirer"],"r":0,"e":"En transfert FR → sol, il s'appuie sur l'accoudoir ou l'assise.","s":4},{"q":"Quelle est la position du transporteur pour le transfert FR → sol ?","o":["Semi-fléchie ou accroupie","Debout, jambes tendues","À genoux, le dos droit","Assis au sol, dos droit"],"r":0,"e":"La position basse protège le rachis du transporteur.","s":4},{"q":"Quelle est l'indication de la « cadeirinha » (chaise à porteurs) ?","o":["Les petits et moyens parcours","Les longs parcours","Les patients totalement dépendants","Les escaliers uniquement"],"r":0,"e":"L'australienne est réservée aux longs parcours.","s":4},{"q":"Que soutient le membre supérieur libre dans la cadeirinha ?","o":["L'ischion du patient","La nuque","Le bassin postérieur","Les cuisses"],"r":0,"e":"Le patient, lui, enlace les transporteurs.","s":4},{"q":"Comment se placent les transporteurs dans la cadeirinha ?","o":["Face à face, de profil au chemin","Côte à côte, face au trajet à parcourir","Dos à dos, de profil au chemin","L'un derrière l'autre, face au trajet"],"r":0,"e":"Ils tournent à la fin pour déposer le patient, en pas parallèle ou croisé.","s":4},{"q":"Que faire si les deux surfaces ne peuvent pas être au même niveau ?","o":["La surface d'arrivée doit être plus basse","La surface de départ doit être plus basse","Le niveau des surfaces importe peu","Le transfert doit alors être annulé"],"r":0,"e":"Règle valable pour les transferts à 1 et à 2 transporteurs.","s":4},{"q":"Quel angle entre les surfaces pour un transfert à 1 transporteur ?","o":["45°","90°","0°, surfaces parallèles","30°"],"r":0,"e":"À 2 transporteurs, les surfaces sont parallèles ; à 1, elles font 45°.","s":4},{"q":"Que faut-il faire du fauteuil roulant avant le transfert ?","o":["Freiner, ôter accoudoir et repose-pied côté transfert","Le laisser libre, pour pouvoir l'ajuster","Retirer les deux accoudoirs, sans freiner","Relever le dossier, puis desserrer les deux freins"],"r":0,"e":"C'est la deuxième étape de la procédure.","s":4},{"q":"Pourquoi positionner les pieds du patient en position intermédiaire ?","o":["Pour éviter une position lésionnelle en fin de transfert","Pour faciliter la prise du kiné au niveau des genoux","Pour éviter les escarres sur les talons pendant le transfert","Pour améliorer l'équilibre du fauteuil roulant"],"r":0,"e":"C'est une anticipation de la position finale.","s":4},{"q":"Où doit être tournée la tête du kiné pendant le pivot ?","o":["Du côté du transfert, pour contrôler la manœuvre","Vers le patient, pour garder le contact visuel","Vers le sol, pour surveiller la position des pieds","Vers le point de départ, pour garder un repère"],"r":0,"e":"C'est la huitième étape de la procédure à 1 transporteur.","s":4},{"q":"Quelle aide technique est indiquée pour les patients totalement dépendants ?","o":["Le lève-personne","La planche de transfert","Le disque de transfert","La ceinture de transfert"],"r":0,"e":"Planche et disque sont réservés aux patients partiellement dépendants.","s":4},{"q":"Combien de critères comporte la grille d'évaluation d'un transfert ?","o":["Sept","Cinq","Six","Neuf"],"r":0,"e":"Raisonnement clinique, sécurité, feedback, position patient, position kinés, commandes verbales, exécution technique.","s":4},{"q":"Les 8 procédures d'un transfert commencent par :","o":["La sélection du transfert","L'évaluation du patient","L'information au patient","Les contacts manuels"],"r":0,"e":"Elle porte sur le type de transfert, le nombre de kinés, l'évaluation du lieu et le trajet.","s":4},{"q":"L'évaluation du patient avant un transfert porte sur :","o":["La pathologie, la dépendance et l'alitement","Le seul poids du patient, mesuré avant le transfert","La seule taille du patient, debout","L'âge du patient, et rien d'autre"],"r":0,"e":"Elle conditionne le choix du type de transfert et du nombre de transporteurs. La pathologie peut être spastique ou flasque ; on évalue le degré de dépendance et les conditions d'alitement.","s":4},{"q":"L'information au patient a pour effets :","o":["Une meilleure synchronisation et moins d'anxiété","Un allongement inutile de la durée du transfert","Une baisse de la collaboration, par excès de consignes","Une hausse du risque de chute, par distraction"],"r":0,"e":"Elle doit être claire et simple, accompagnée d'une attitude sûre et confiante et de l'historique des transferts. La coordination est aussi améliorée.","s":4},{"q":"La position du transporteur prend en compte :","o":["Centre de gravité, base, leviers, flexion, pieds et force","La seule force musculaire du transporteur, sans autre critère","La seule taille du transporteur, comparée au patient","La seule vitesse d'exécution du transfert"],"r":0,"e":"C'est la cinquième des huit procédures. La base est la base de sustentation ; les leviers sont avantageux et les membres légèrement fléchis.","s":4},{"q":"Parmi les six règles des contacts manuels figure :","o":["Que le contact transmette sécurité et confort","Que la prise soit ferme, voire douloureuse","Que les mains soutiennent par le dessus","Que les pulpes appuient fortement sur le segment tenu"],"r":0,"e":"S'y ajoutent le bon soutien du tronc, le choix adapté des prises, la main en coupe et l'évitement des mains moites.","s":4},{"q":"Le positionnement du patient doit se faire :","o":["Au début et à la fin du transfert","À la fin du transfert, seulement","Au début du transfert, et seulement alors","Pendant le déplacement, en continu"],"r":0,"e":"Cela augmente la collaboration et diminue les risques de chute et de lésion.","s":4},{"q":"La règle de choix du transfert énonce que :","o":["Plus le patient est fonctionnel, moins il faut de soutien","Plus le patient est fonctionnel, plus il faut de soutien du kiné","Le soutien reste constant, quel que soit le patient","Le nombre de kinés ne dépend que du poids du patient"],"r":0,"e":"Une fonctionnalité moindre impose plus de soutien, voire plusieurs kinés.","s":4},{"q":"Dans le transfert à 3 transporteurs, le poste A est tenu par :","o":["Le plus grand et le plus fort, chef d'équipe","Le plus petit et le moins fort du groupe","N'importe quel transporteur, selon les disponibilités","Le moins expérimenté, guidé par les autres"],"r":0,"e":"Il assure le soutien cervical, par l'occiput et les épines des omoplates ; le poste C revient au plus petit et au moins fort.","s":4},{"q":"Le poste B du transfert à 3 transporteurs prend :","o":["La région lombaire et l'arrière des cuisses","L'occiput et les épines des omoplates","Le dessus du creux poplité et des malléoles","La tête seule, en tractant doucement"],"r":0,"e":"Le poste C prend au-dessus du creux poplité et au-dessus des malléoles.","s":4},{"q":"Parmi les points d'exécution du transfert à 3/4 transporteurs figure :","o":["Utiliser le levier le plus court possible","Utiliser le levier le plus long possible, bras tendus","Travailler sans synchronisation stricte","Éviter la mise à niveau des surfaces"],"r":0,"e":"Le mouvement doit être synchrone, chaque transporteur ayant sa fonction, et les surfaces mises à niveau.","s":4},{"q":"Dans l'alternative avec drap, la prise se fait :","o":["En pronation, avec le drap en tension","En supination, avec le drap tendu","En pronation, avec le drap détendu","D'une seule main, avec le drap roulé en boule"],"r":0,"e":"Le drap enroulé est plus résistant, les lits sont parallèles, et les prises portent sur tête, ceinture scapulaire, tronc, ceinture pelvienne et membres inférieurs.","s":4},{"q":"Dans la technique australienne, les transporteurs doivent :","o":["Être de même taille et face au trajet","Être de tailles différentes, le plus grand devant","Se placer dos au trajet, face à face","Se placer de profil, côte à côte"],"r":0,"e":"Elle est indiquée chez les patients partiellement dépendants, pour les longs parcours, les escaliers, le réajustement au lit et le passage au sol.","s":4},{"q":"Dans la technique australienne, l'élévation se fait :","o":["Par les membres inférieurs, de la flexion à l'extension","Par la force des bras, en tirant le patient vers le haut","Par le tronc, en se redressant d'un coup","Par traction du drap, tendu sous le patient"],"r":0,"e":"L'épaule du transporteur appuie sur la face latérale de la grille costale, sous l'aisselle, sans comprimer.","s":4},{"q":"Dans la variante australienne pour le passage du fauteuil au sol, le membre supérieur libre :","o":["S'appuie sur l'accoudoir ou l'assise du fauteuil","Soutient la tête du patient pendant la descente","Reste libre, le long du corps du transporteur","Tient le drap enroulé sous le bassin du patient au sol"],"r":0,"e":"Dans la variante de réajustement au lit, il s'appuie sur le lit pour faciliter le push-up, sans traîner le patient. Le transporteur est semi-fléchi ou accroupi.","s":4},{"q":"Dans la cadeirinha, les transporteurs se placent :","o":["Face à face, de profil au chemin, puis tournent","Côte à côte, face au chemin, sans se tourner","En file, l'un derrière l'autre, sur le chemin","Dos à dos, de profil au chemin, en pas croisés"],"r":0,"e":"Ils ne doivent pas marcher en pas parallèle ou croisé ; le patient les enlace. Ils tournent à la fin pour déposer le patient.","s":4},{"q":"Dans la cadeirinha, le membre supérieur libre soutient :","o":["L'ischion","La région lombaire","La tête","Les cuisses"],"r":0,"e":"La prise sous les cuisses, d'avant-bras ou de poignet, forme le siège.","s":4},{"q":"Dans un transfert à 2 transporteurs entre fauteuil et lit, le chef d'équipe est :","o":["Celui placé derrière, qui tient le tronc et les deux bras","Celui placé sur le côté, qui tient cuisses et jambes","Le patient lui-même, qui donne le signal","Le plus grand des deux, quelle que soit sa place"],"r":0,"e":"Les membres supérieurs du patient sont croisés devant lui ; le second transporteur soutient latéralement cuisses et jambes. Il utilise une prise croisée aux avant-bras.","s":4},{"q":"Dans le transfert à 2 transporteurs, le déplacement latéral se fait :","o":["Par le déplacement des jambes des transporteurs","Par la traction des bras des transporteurs","Par un drap de glissement tiré à deux","Par la rotation du tronc des transporteurs"],"r":0,"e":"Les surfaces doivent être au même niveau et parallèles ; à défaut, la surface d'arrivée doit être plus basse.","s":4},{"q":"Pour un transfert à un seul transporteur du lit vers le fauteuil, l'angle entre les surfaces est de :","o":["45°","90°","0°","180°"],"r":0,"e":"Le fauteuil doit être freiné, l'accoudoir retiré et le repose-pied relevé.","s":4},{"q":"Le kiné informe le patient de l'aide qu'il peut apporter, à savoir :","o":["Se pencher, s'appuyer sur le kiné et pousser des jambes","Rester totalement passif, pour ne pas gêner le pivot du kiné","Tirer sur le cou du kiné, bras tendus","Se lever seul, sans prendre appui"],"r":0,"e":"Les pieds du patient sont placés en position intermédiaire, pour éviter une position lésionnelle en fin de transfert.","s":4}]};
